297	        std::io::Error::new(e.kind(), format!("could not write key file: {e}"))
298	    })?;
299	
300	    if unsafe { libc::fsync(fd) } != 0 {
301	        let e = std::io::Error::last_os_error();
302	        return Err(std::io::Error::new(
303	            e.kind(),
304	            format!("could not flush key file: {e}"),
305	        ));
306	    }
