311	#[cfg(unix)]
312	fn write_all(fd: RawFd, mut data: &[u8]) -> std::io::Result<()> {
313	    while !data.is_empty() {
314	        let n = unsafe {
315	            libc::write(fd, data.as_ptr().cast::<libc::c_void>(), data.len())
316	        };
317	        if n < 0 {
318	            let e = std::io::Error::last_os_error();
319	            if e.raw_os_error() == Some(libc::EINTR) {
320	                continue;
321	            }
322	            return Err(e);
323	        }
324	        if n == 0 {
325	            return Err(std::io::Error::new(
326	                std::io::ErrorKind::WriteZero,
327	                "incomplete write to key file",
328	            ));
329	        }
330	        data = &data[n as usize..];
331	    }
332	    Ok(())
333	}
