1	/*
2	 * permfail.c -- LD_PRELOAD shim for wrapfile keygen permission tests.
3	 *
4	 * Two jobs:
5	 *
6	 * 1. Tracing. For the file the guest creates with open(O_CREAT|...) it logs
7	 *    to WRAPFILE_TEST_TRACE_FILE (one line per event):
8	 *
9	 *      BORN        fd=N mode=0oNNNN   mode right after the creating open()
10	 *      FCHMOD      ret=0/-1 mode=0oNNNN
11	 *      FSTAT       ret=0/-1 mode=0oNNNN size=N   (mode reported to guest)
12	 *      FIRST_WRITE mode=0oNNNN size=N  immediately before the first write()
13	 *      WRITE       off=N req=N ret=N [hex=...]   each write() on the key fd;
14	 *                    ret=-1 errno=ENAME for injected faults
15	 *      FSYNC       ret=0/-1
16	 *      CLOSE       ret=0/-1 [errno=ENAME]   close() on the key fd; the
17	 *                    descriptor is really released either way (Linux
18	 *                    semantics), errno= marks an injected report
19	 *      UNLINK      ret=0/-1 [errno=ENAME]   each unlink() the guest attempts
20	 *
21	 *    FIRST_WRITE with mode=0o600 and size=0 proves the program had both set
22	 *    and *confirmed* 0600 before a single key byte was written. The WRITE
23	 *    stream (off ascending from 0 with no gaps or overlaps, ending at 32)
24	 *    proves partial writes were resumed without duplicating or dropping
25	 *    bytes, and FSYNC ret=0 after the last WRITE proves the key was synced
26	 *    to disk before the program reported success.
27	 *
28	 * 2. Fault injection (only for a descriptor the guest itself created):
29	 *      WRAPFILE_TEST_FAIL_FCHMOD=1      fchmod() fails with EPERM
30	 *      WRAPFILE_TEST_FAIL_FSTAT=1       fstat()/fstat64() fail (EBADF), so the
31	 *                                        resulting mode cannot be confirmed
32	 *      WRAPFILE_TEST_LIE_MODE=OCTAL     fstat reports these low 12 mode bits
33	 *                                        (e.g. 0000) while the real fchmod
34	 *                                        succeeded -- a filesystem that silently
35	 *                                        stores another mode
36	 *      WRAPFILE_TEST_PARTIAL_WRITE=N    write() accepts at most N bytes per
37	 *                                        call (a kernel that only takes part
38	 *                                        of the buffer)
39	 *      WRAPFILE_TEST_WRITE_EINTR=N      the first N write() calls fail with
40	 *                                        EINTR, then writes succeed normally
41	 *      WRAPFILE_TEST_FAIL_WRITE_AFTER=N after N bytes in total have landed,
42	 *                                        write() fails with EIO (the last
43	 *                                        partial write is clamped so exactly
44	 *                                        N bytes are on disk before the error)
45	 *      WRAPFILE_TEST_WRITE_ZERO_AFTER=N once N bytes in total have landed,
46	 *                                        write() returns 0 without setting
47	 *                                        errno: no progress, yet no error
48	 *                                        either (the last real write is
49	 *                                        clamped so exactly N bytes are on
50	 *                                        disk first). Distinct from
51	 *                                        PARTIAL_WRITE (some progress every
52	 *                                        call) and from EINTR/EIO (an error
53	 *                                        is reported).
54	 *      WRAPFILE_TEST_FAIL_FSYNC=1       fsync() fails with EIO
55	 *      WRAPFILE_TEST_FAIL_CLOSE=1       close() on the key fd reports EIO.
56	 *                                       The descriptor is really closed
57	 *                                       first (on Linux a failed close()
58	 *                                       still releases it), so the guest
59	 *                                       must not retry the close
60	 *      WRAPFILE_TEST_CLOSE_EINTR=1      close() on the key fd reports EINTR
61	 *                                       after really releasing the
62	 *                                       descriptor -- the recoverable
63	 *                                       interruption, not a failure
64	 *      WRAPFILE_TEST_FAIL_UNLINK=1      unlink() fails with EACCES without
65	 *                                       removing anything (the system
66	 *                                       refuses the cleanup)
67	 *      WRAPFILE_TEST_TRACE_BYTES=1      append hex=... of the bytes each
68	 *                                        write() actually landed, so tests can
69	 *                                        reconstruct the byte stream and check
70	 *                                        nothing secret leaks to stdout/stderr
71	 *
72	 * The shim only activates inside an executable whose basename starts with
73	 * "wrapfile" (checked via /proc/self/exe), so a wrapper shell used to set
74	 * the umask is never affected. After execve() the guest starts with a fresh
75	 * table, so only the guest's own O_CREAT descriptor (the key file) is
76	 * tracked; stdout/stderr and unrelated fds pass through untouched.
77	 */
78	
